package com.bank.isr.model;

import java.util.*;

// Tracks the replica set, the in-sync subset (ISR), and the leader.
public class PartitionReplicas {
    private final int replicationFactor;
    private final Set<String> inSync = new LinkedHashSet<>();
    private String leader;

    public PartitionReplicas(int replicationFactor, List<String> brokers) {
        this.replicationFactor = replicationFactor;
        inSync.addAll(brokers);
        this.leader = brokers.get(0);
    }

    public int isrSize() { return inSync.size(); }
    public Set<String> getInSync() { return inSync; }
    public int getReplicationFactor() { return replicationFactor; }

    // A follower falls out of the ISR (lag or broker down).
    public void removeFromIsr(String broker) {
        inSync.remove(broker);
        if (broker.equals(leader) && !inSync.isEmpty()) leader = inSync.iterator().next();
    }
    public void addToIsr(String broker) { inSync.add(broker); }
}
