package com.bank.isr.broker;

import com.bank.isr.exception.NotEnoughReplicasException;
import com.bank.isr.model.PartitionReplicas;
import java.util.logging.*;

public class WriteBroker {
    private static final Logger log = Logger.getLogger(WriteBroker.class.getName());

    private final int minInsyncReplicas;

    public WriteBroker(int minInsyncReplicas) { this.minInsyncReplicas = minInsyncReplicas; }

    // acks=all write: must persist to EVERY ISR member AND ISR must be >= min.insync.replicas.
    public void writeAcksAll(PartitionReplicas p, String payload) {
        if (p.isrSize() < minInsyncReplicas) {
            throw new NotEnoughReplicasException("ISR=" + p.isrSize()
                + " < min.insync.replicas=" + minInsyncReplicas
                + " — rejecting write to avoid acknowledging unsafe data: '" + payload + "'");
        }
        // persist to all ISR members (acks=all), then acknowledge
        log.info(() -> "Write OK '" + payload + "' persisted to ISR=" + p.getInSync()
            + " (size " + p.isrSize() + " >= " + minInsyncReplicas + ")");
    }
}
