package com.bank.isr;

import com.bank.isr.broker.WriteBroker;
import com.bank.isr.exception.NotEnoughReplicasException;
import com.bank.isr.model.PartitionReplicas;
import java.util.List;
import java.util.logging.*;

public class IsrDemo {
    private static final Logger log = Logger.getLogger(IsrDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Replication factor 3, min.insync.replicas 2, acks=all (the bank standard).
        PartitionReplicas partition = new PartitionReplicas(3,
            List.of("broker-1", "broker-2", "broker-3"));
        WriteBroker broker = new WriteBroker(2);

        // Healthy: ISR=3 >= 2 -> write accepted.
        broker.writeAcksAll(partition, "TRANSFER SAV2001->CUR3001 50000");

        // Lose one broker: ISR=2 >= 2 -> still accepted (tolerates 1 failure).
        partition.removeFromIsr("broker-3");
        broker.writeAcksAll(partition, "TRANSFER CUR3001->SAV2001 20000");

        // Lose a second broker: ISR=1 < 2 -> REJECTED (refuse unsafe write).
        partition.removeFromIsr("broker-2");
        try {
            broker.writeAcksAll(partition, "TRANSFER SAV2001->CUR3001 99999");
        } catch (NotEnoughReplicasException ex) {
            log.severe("Write rejected: " + ex.getMessage());
            log.warning("Durability chosen over availability: refuse rather than risk loss.");
        }
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
